/**
 * continued-fraction-expansion.ts - Periodic Continued Fraction of a Square Root
 *
 * ---------------------------------------------------------------------------
 * What it does
 * ---------------------------------------------------------------------------
 * The continued fraction expansion of sqrt(D) for a nonsquare D is periodic:
 * sqrt(D) = [a0; a1, ..., aL-1, 2*a0, a1, ...]. The expansion is generated by
 * the recurrence m = d*a - m, d = (D - m^2)/d, a = floor((a0 + m)/d), starting
 * from a0 = floor(sqrt(D)), m = 0, d = 1. The period ends when a reaches 2*a0.
 * The convergents of this expansion also give the fundamental Pell solution.
 *
 * ---------------------------------------------------------------------------
 * Complexity
 * ---------------------------------------------------------------------------
 *   Time:  O(L) for a period of length L
 *   Space: O(L) to store the partial quotients
 *
 * ---------------------------------------------------------------------------
 * Visualization mapping
 * ---------------------------------------------------------------------------
 *   - Each partial quotient is a bar, with a0 fixed and the period highlighted.
 *   - The recurrence state (m, d) is shown alongside the current quotient.
 *   - The final frame marks the completed period SORTED.
 */

import type { AlgorithmModule, EntityState, VisualEntity, VisualFrame } from "@/types";

/** One bar entity for a partial quotient. */
function bar(index: number, value: number, state: EntityState): VisualEntity {
    return {
        id: `bar-${index}`,
        type: "bar" as const,
        label: String(value),
        value,
        state,
        x: 0,
        y: 0,
        width: 0,
        height: 0,
        metadata: { index, value },
    };
}

/** Build bars for a0 and the partials discovered so far. */
function makeBars(a0: number, partials: number[], complete: boolean): VisualEntity[] {
    const entities: VisualEntity[] = [bar(0, a0, "pivot")];
    for (let i = 0; i < partials.length; i += 1) {
        entities.push(bar(i + 1, partials[i] ?? 0, complete ? "sorted" : "active"));
    }
    return entities;
}

/** The periodic continued fraction generator. */
function* run(input: unknown): Generator<VisualFrame, void, unknown> {
    const task = (input as { D?: number } | null) ?? {};
    const D = typeof task.D === "number" ? Math.trunc(task.D) : 23;
    let step = 0;

    if (!Number.isFinite(D) || D < 2 || Number.isInteger(Math.sqrt(D))) {
        yield {
            stepNumber: 0,
            entities: [bar(0, 0, "highlight")],
            edges: [],
            description: "A nonsquare D >= 2 is required for a periodic expansion.",
            codeLineNumber: 0,
            layout: "array",
            meta: { D, a0: 0, partials: [], period: 0 },
        };
        return;
    }

    const a0 = Math.floor(Math.sqrt(D));
    const partials: number[] = [];

    yield {
        stepNumber: step,
        entities: makeBars(a0, partials, false),
        edges: [],
        description: `sqrt(${D}) = [${a0}; ...]; a0 = floor(sqrt(${D})) = ${a0}.`,
        codeLineNumber: 0,
        layout: "array",
        meta: { D, a0, partials: [], period: 0 },
    };
    step += 1;

    let m = 0;
    let d = 1;
    let a = a0;

    for (let i = 0; i < 10000; i += 1) {
        m = d * a - m;
        d = Math.floor((D - m * m) / d);
        a = Math.floor((a0 + m) / d);
        partials.push(a);

        yield {
            stepNumber: step,
            entities: makeBars(a0, partials, false),
            edges: [],
            description:
                `Partial ${i + 1}: m=${m}, d=${d}, a=${a}; ` +
                `the recurrence keeps m squared congruent to ${D} modulo d.`,
            codeLineNumber: 2,
            layout: "array",
            meta: { D, a0, partials: partials.slice(), period: 0, m, d },
        };
        step += 1;

        if (a === 2 * a0) {
            break;
        }
    }

    yield {
        stepNumber: step,
        entities: makeBars(a0, partials, true),
        edges: [],
        description:
            `Period complete: sqrt(${D}) = [${a0}; <${partials.join(", ")}>] ` +
            `with period length ${partials.length}.`,
        codeLineNumber: 5,
        layout: "array",
        meta: { D, a0, partials: partials.slice(), period: partials.length },
    };
}

/** The periodic continued fraction module. */
const module: AlgorithmModule = {
    education: {
        intuition:
            "The square root of a nonsquare integer has a continued fraction that repeats forever. The repetition can be found with a three-number recurrence involving m, d, and the current partial quotient. When the quotient reaches twice the leading term, one full period is complete, and the repeating block encodes both the value of the square root and the fundamental solution of its Pell equation.",
        invariants: [
            "At every step m squared is congruent to D modulo d.",
            "The partial quotients a are positive integers with a = 2*a0 exactly at the end of a period.",
            "The convergent built from the partials approaches sqrt(D) monotonically in alternate directions.",
        ],
        correctness:
            "Writing sqrt(D) = a0 + (sqrt(D) - a0) and rationalizing produces the recurrence m = d*a - m, d = (D - m^2)/d, a = floor((a0 + m)/d). Each step is an exact algebraic rewrite, so the partial quotients are those of sqrt(D). The reduced quadratic surds cycle through finitely many states, guaranteeing a repeat, and the first repeat occurs when a = 2*a0, which marks the end of the minimal period. The convergents then satisfy p^2 - D*q^2 = 1 or -1, giving Pell solutions.",
        complexityRationale:
            "Each iteration performs constant-time integer arithmetic, so generating a period of length L takes O(L) time. Storing the L partial quotients uses O(L) space.",
        uses: [
            "Generating the fundamental solution of Pell's equation",
            "Representing quadratic irrationals exactly in number theory",
            "Producing best rational approximations to square roots",
        ],
        references: [
            "Niven and Zuckerman, An Introduction to the Theory of Numbers, Chapter 7",
            "Knuth, The Art of Computer Programming, Vol. 2, Section 4.5.3",
        ],
        workedExample:
            "For D = 23, a0 = 4. The recurrence yields partials 1, 3, 1, 8, at which point a = 8 = 2*a0, so sqrt(23) = [4; 1, 3, 1, 8, ...] with period length 4. Its convergents include 24/5, and 24 squared minus 23 times 5 squared equals 1.",
    },
    id: "continued-fraction-expansion",
    name: "Continued Fraction Expansion (Periodic)",
    category: "math",
    complexity: { time: "O(L)", space: "O(L)" },
    defaultInput: { D: 23 },
    visualType: "array",
    run,
    pseudocode: [
        "set a0 = floor(sqrt(D)), m = 0, d = 1, a = a0",
        "repeat the recurrence until the period closes",
        "set m = d*a - m",
        "set d = (D - m squared)/d and a = floor((a0 + m)/d)",
        "append a to the partial quotient list",
        "stop when a = 2*a0, completing one period",
        "done: report the repeating block of the expansion",
    ],
};

export default module;
